import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
INF = 10**9
d = [[INF] * n for _ in range(n)]
for i in range(n):
    d[i][i] = 0
pos = 2
for _ in range(m):
    u, v = int(data[pos]), int(data[pos + 1])
    pos += 2
    d[u][v] = min(d[u][v], 1)
    d[v][u] = min(d[v][u], 1)
a, b = int(data[pos]), int(data[pos + 1])
for k in range(n):
    for i in range(n):
        for j in range(n):
            if d[i][k] + d[k][j] < d[i][j]:
                d[i][j] = d[i][k] + d[k][j]
print(d[a][b] if d[a][b] < INF else -1)

